-- BDTECH360 private software factory. Additive only; no existing tables changed.
CREATE TABLE "FactoryCompany" ("id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL, "legalName" TEXT NOT NULL, "relationship" TEXT NOT NULL, "industry" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "contractStatus" TEXT NOT NULL DEFAULT 'INTERNAL', "supportStatus" TEXT NOT NULL DEFAULT 'STANDARD', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "FactoryTemplate" ("id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "createdBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "FactoryTemplateVersion" ("id" TEXT NOT NULL PRIMARY KEY, "templateId" TEXT NOT NULL, "version" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "configurationSchema" TEXT NOT NULL, "navigation" TEXT NOT NULL, "workflows" TEXT NOT NULL, "acceptanceTests" TEXT NOT NULL, "releaseNotes" TEXT NOT NULL, "sourceCommit" TEXT, "approvedBy" TEXT, "approvedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FactoryTemplateVersion_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "FactoryTemplate" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "FactoryModule" ("id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "FactoryModuleVersion" ("id" TEXT NOT NULL PRIMARY KEY, "moduleId" TEXT NOT NULL, "version" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'APPROVED', "capabilities" TEXT NOT NULL, "dependencies" TEXT NOT NULL, "compatibility" TEXT NOT NULL, "acceptanceTests" TEXT NOT NULL, "releaseNotes" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FactoryModuleVersion_moduleId_fkey" FOREIGN KEY ("moduleId") REFERENCES "FactoryModule" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "FactoryTemplateModule" ("id" TEXT NOT NULL PRIMARY KEY, "templateVersionId" TEXT NOT NULL, "moduleVersionId" TEXT NOT NULL, "required" BOOLEAN NOT NULL DEFAULT true, "configuration" TEXT NOT NULL DEFAULT '{}', CONSTRAINT "FactoryTemplateModule_templateVersionId_fkey" FOREIGN KEY ("templateVersionId") REFERENCES "FactoryTemplateVersion" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "FactoryTemplateModule_moduleVersionId_fkey" FOREIGN KEY ("moduleVersionId") REFERENCES "FactoryModuleVersion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "FactoryApplication" ("id" TEXT NOT NULL PRIMARY KEY, "companyId" TEXT NOT NULL, "templateVersionId" TEXT NOT NULL, "name" TEXT NOT NULL, "deploymentModel" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "configuration" TEXT NOT NULL, "branding" TEXT NOT NULL, "currentReleaseId" TEXT, "domain" TEXT, "healthStatus" TEXT NOT NULL DEFAULT 'UNKNOWN', "lastHealthCheckAt" DATETIME, "createdBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "FactoryApplication_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "FactoryCompany" ("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "FactoryApplication_templateVersionId_fkey" FOREIGN KEY ("templateVersionId") REFERENCES "FactoryTemplateVersion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "FactoryConfigRevision" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "configuration" TEXT NOT NULL, "branding" TEXT NOT NULL, "reason" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FactoryConfigRevision_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FactoryMembership" ("id" TEXT NOT NULL PRIMARY KEY, "companyId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "FactoryMembership_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "FactoryCompany" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FactoryProvisioningRun" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "status" TEXT NOT NULL, "checks" TEXT NOT NULL, "error" TEXT, "startedBy" TEXT NOT NULL, "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" DATETIME, CONSTRAINT "FactoryProvisioningRun_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FactoryDeployment" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "environment" TEXT NOT NULL, "status" TEXT NOT NULL, "adapter" TEXT NOT NULL, "details" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "FactoryDeployment_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FactoryRelease" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "templateVersionId" TEXT NOT NULL, "version" TEXT NOT NULL, "status" TEXT NOT NULL, "releaseNotes" TEXT NOT NULL, "impactAssessment" TEXT NOT NULL, "rollbackPlan" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FactoryRelease_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "FactoryRelease_templateVersionId_fkey" FOREIGN KEY ("templateVersionId") REFERENCES "FactoryTemplateVersion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "FactoryApproval" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "action" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "requestedBy" TEXT NOT NULL, "decidedBy" TEXT, "note" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "decidedAt" DATETIME, CONSTRAINT "FactoryApproval_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FactoryBackup" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "location" TEXT NOT NULL, "sha256" TEXT NOT NULL, "byteSize" INTEGER NOT NULL, "integrity" TEXT NOT NULL, "definitionPath" TEXT NOT NULL, "status" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FactoryBackup_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FactoryIntegration" ("id" TEXT NOT NULL PRIMARY KEY, "companyId" TEXT NOT NULL, "providerKey" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DISABLED', "credentialRef" TEXT, "configuration" TEXT NOT NULL DEFAULT '{}', "lastCheckedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "FactoryChangeRequest" ("id" TEXT NOT NULL PRIMARY KEY, "templateId" TEXT, "kind" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "disposition" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "requestedBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "FactoryChangeRequest_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "FactoryTemplate" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "FactoryAuditEvent" ("id" TEXT NOT NULL PRIMARY KEY, "companyId" TEXT, "applicationId" TEXT, "actorUserId" TEXT NOT NULL, "action" TEXT NOT NULL, "resource" TEXT NOT NULL, "metadata" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FactoryAuditEvent_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "FactoryCompany" ("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "FactoryAuditEvent_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "FactoryApplication" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "FactoryContact" ("id" TEXT NOT NULL PRIMARY KEY, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT, "phone" TEXT, "notes" TEXT, "createdBy" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "FactoryContact_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "FactoryCompany" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "FactoryCompany_slug_key" ON "FactoryCompany"("slug");
CREATE UNIQUE INDEX "FactoryTemplate_slug_key" ON "FactoryTemplate"("slug");
CREATE UNIQUE INDEX "FactoryTemplateVersion_templateId_version_key" ON "FactoryTemplateVersion"("templateId", "version");
CREATE UNIQUE INDEX "FactoryModule_slug_key" ON "FactoryModule"("slug");
