CREATE UNIQUE INDEX "FactoryTemplateModule_templateVersionId_moduleVersionId_key" ON "FactoryTemplateModule"("templateVersionId", "moduleVersionId");
CREATE UNIQUE INDEX "FactoryApplication_domain_key" ON "FactoryApplication"("domain");
CREATE UNIQUE INDEX "FactoryConfigRevision_applicationId_revision_key" ON "FactoryConfigRevision"("applicationId", "revision");
CREATE UNIQUE INDEX "FactoryMembership_companyId_userId_key" ON "FactoryMembership"("companyId", "userId");
CREATE UNIQUE INDEX "FactoryDeployment_applicationId_environment_key" ON "FactoryDeployment"("applicationId", "environment");
CREATE UNIQUE INDEX "FactoryRelease_applicationId_version_key" ON "FactoryRelease"("applicationId", "version");
CREATE UNIQUE INDEX "FactoryIntegration_companyId_providerKey_key" ON "FactoryIntegration"("companyId", "providerKey");
